/**
 * Append-only event ledger. Balances are derived by folding the event stream.
 */

/**
 * Apply a single event to a balance map: credits add, debits subtract. Shared
 * by fold() and the snapshot cache so both stay arithmetically identical.
 */
export function applyEvent(balances, event) {
  const current = balances.get(event.account) ?? 0
  balances.set(event.account, current + (event.type === 'credit' ? event.amountCents : -event.amountCents))
}

export function createLedger() {
  const events = []
  return {
    append(event) {
      events.push({ seq: events.length, ...event })
    },
    eventCount() {
      return events.length
    },
    /** O(1) access to the event at stream position `seq`, without copying. */
    eventAt(seq) {
      return events[seq]
    },
    fold() {
      const balances = new Map()
      for (const event of events) {
        applyEvent(balances, event)
      }
      return Object.fromEntries(balances)
    },
    events() {
      return [...events]
    },
  }
}

/**
 * Balance snapshot cache. Folding the full stream on every read is expensive,
 * so each ledger gets its own cache (keyed in a WeakMap) that is rebased by a
 * full fold at most once every REFRESH_EVERY events. Events appended in
 * between are applied incrementally on top of the cached balances, so a read
 * is always exact: getBalance(ledger, account) always equals what a direct
 * fold of the current event stream would produce (README invariant 3), and
 * transfer() therefore validates against the true balance (invariant 2).
 */
import { applyEvent } from './ledger.js'

const REFRESH_EVERY = 8

let caches = new WeakMap()

export function getBalance(ledger, account) {
  let cache = caches.get(ledger)
  const count = ledger.eventCount()
  if (cache === undefined || count < cache.atCount || count - cache.atCount >= REFRESH_EVERY) {
    // No usable cache, or the stale slice has grown too large: rebase with a
    // full fold — at most once per REFRESH_EVERY events.
    cache = { atCount: count, balances: new Map(Object.entries(ledger.fold())) }
  } else if (count > cache.atCount) {
    // Bring the cached balances exactly up to the current stream tip instead
    // of serving values that lag behind it.
    const byIndex = typeof ledger.eventAt === 'function'
    const copied = byIndex ? null : ledger.events()
    for (let seq = cache.atCount; seq < count; seq++) {
      applyEvent(cache.balances, byIndex ? ledger.eventAt(seq) : copied[seq])
    }
    cache.atCount = count
  }
  caches.set(ledger, cache)
  return cache.balances.get(account) ?? 0
}

export function resetSnapshotCache() {
  caches = new WeakMap()
}

