// Randomized invariant verification (scratch, not part of the test suite).
// Checks README invariants after every operation:
//   1. conservation of total balance, 2. no overdraft, 3. getBalance === fold.
import assert from 'node:assert/strict'
import { createLedger, transfer, getBalance, resetSnapshotCache, createRebateHook } from './src/index.js'

let seed = 987654321
const rand = (n) => {
  seed = (seed * 1103515245 + 12345) % 2147483648
  return Math.floor((seed / 2147483648) * n)
}

const checkExact = (ledger, accounts) => {
  const folded = ledger.fold()
  for (const acct of accounts) {
    assert.equal(getBalance(ledger, acct), folded[acct] ?? 0, `getBalance(${acct}) != fold for ledger`)
  }
  return folded
}

// --- 1) randomized single-ledger fuzz, with and without rebate hooks ---
for (let trial = 0; trial < 300; trial++) {
  resetSnapshotCache()
  const ledger = createLedger()
  const accounts = ['a', 'b', 'c', 'd']
  let total = 0
  for (const acct of accounts) {
    const fund = 1000 + rand(5000)
    ledger.append({ type: 'credit', account: acct, amountCents: fund, ts: 0, id: `fund-${acct}` })
    total += fund
  }
  const hook = rand(2) ? createRebateHook(ledger, 1 + rand(60)) : null
  for (let op = 0; op < 80; op++) {
    const folded = checkExact(ledger, accounts)
    const sum = Object.values(folded).reduce((s, v) => s + v, 0)
    assert.equal(sum, total, 'invariant 1 broken: total changed')
    for (const acct of accounts) assert.ok((folded[acct] ?? 0) >= 0, 'invariant 2 broken: overdraft on ' + acct)

    const from = accounts[rand(accounts.length)]
    const to = accounts[rand(accounts.length)]
    const amount = 1 + rand(2000)
    const before = ledger.eventCount()
    try {
      transfer(ledger, from, to, amount, hook ? { onSettled: hook } : {})
    } catch (e) {
      assert.match(String(e.message), /insufficient funds/)
      assert.equal(ledger.eventCount(), before, 'failed transfer appended events')
    }
    if (op % 7 === 3) {
      // direct appends (extra funding) land between reads: delta path must track them
      const fund = 1 + rand(500)
      ledger.append({ type: 'credit', account: accounts[rand(accounts.length)], amountCents: fund, ts: 0, id: `top-${op}` })
      total += fund
    }
  }
  checkExact(ledger, accounts)
}

// --- 2) two ledgers interleaved: caches must never cross-contaminate ---
for (let trial = 0; trial < 100; trial++) {
  resetSnapshotCache()
  const l1 = createLedger()
  const l2 = createLedger()
  l1.append({ type: 'credit', account: 'u', amountCents: 4000, ts: 0, id: 'i1' })
  l2.append({ type: 'credit', account: 'v', amountCents: 9000, ts: 0, id: 'i2' })
  for (let op = 0; op < 40; op++) {
    const ledger = rand(2) ? l1 : l2
    try {
      transfer(ledger, rand(2) ? 'u' : 'v', rand(2) ? 'u' : 'v', 1 + rand(1500), {})
    } catch (e) {
      assert.match(String(e.message), /insufficient funds/)
    }
    checkExact(l1, ['u', 'v'])
    checkExact(l2, ['u', 'v'])
    assert.equal(Object.values(l1.fold()).reduce((s, v) => s + v, 0), 4000, 'l1 conservation')
    assert.equal(Object.values(l2.fold()).reduce((s, v) => s + v, 0), 9000, 'l2 conservation')
  }
}

// --- 3) rejection guards and the rebate-rate boundary ---
resetSnapshotCache()
const g = createLedger()
g.append({ type: 'credit', account: 'a', amountCents: 100, ts: 0, id: 'g1' })
assert.throws(() => transfer(g, 'a', 'b', Number.NaN, {}), /amount must be positive/)
assert.throws(() => transfer(g, 'a', 'b', 1.5, {}), /amount must be positive/)
assert.throws(() => transfer(g, 'a', 'b', Infinity, {}), /amount must be positive/)
assert.throws(() => createRebateHook(g, 100), /rebate rate/)

// rate 99 (just under the guard) terminates and conserves
resetSnapshotCache()
const h = createLedger()
h.append({ type: 'credit', account: 'a', amountCents: 1000000, ts: 0, id: 'h1' })
h.append({ type: 'credit', account: 'b', amountCents: 1000000, ts: 0, id: 'h2' })
transfer(h, 'a', 'b', 1000000, { onSettled: createRebateHook(h, 99) })
assert.equal(Object.values(h.fold()).reduce((s, v) => s + v, 0), 2000000, 'rate-99 chain conservation')

console.log('all invariant fuzz checks passed (300 single-ledger trials, 100 two-ledger trials)')
